insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-253', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Half-life of a gaseous decay is 40 min at 0.80 bar initial pressure and 80 min at 0.40 bar. The order and $k$ (from the 0.80 bar run, treating concentration as proportional to $p$) are consistent with', '["second order, because $t_{1/2}$ doubles when $p_0$ is halved","first order, because $t_{1/2}$ is independent of $p_0$","zero order, because $t_{1/2}$ halves when $p_0$ is halved","third order, because $t_{1/2} \\propto p_0^2$"]'::jsonb, 0, 'Second-order $t_{1/2} \propto 1/[\mathrm{A}]_0$. Halving the initial pressure doubles the half-life, which matches the data.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'integrated-half-life') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
